<template>
  <div>
    <pre
      class="language-json"
    ><code ref="highlightedCode" class="language-json">{{ formattedJson }}</code></pre>
  </div>
</template>

<script>
import { Prism } from 'src/utils/prism';
import 'vue-prism-editor/dist/prismeditor.min.css';

export default {
  props: {
    jsonData: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      formattedJson: '',
    };
  },
  watch: {
    jsonData: {
      immediate: true,
      handler(newVal) {
        this.formatAndHighlightJson(newVal);
      },
    },
  },
  methods: {
    formatAndHighlightJson(json) {
      try {
        this.formattedJson = JSON.stringify(json, null, 2);
      } catch (e) {
        this.formattedJson = 'Invalid JSON';
      }
      this.$nextTick(() => {
        Prism.highlightElement(this.$refs.highlightedCode);
      });
    },
  },
};
</script>

